up_sql:
CREATE EXTENSION IF NOT EXISTS postgis;
CREATE EXTENSION IF NOT EXISTS timescaledb CASCADE;

CREATE TABLE IF NOT EXISTS geological_observations (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    timestamp TIMESTAMPTZ NOT NULL,
    location GEOMETRY(POINT, 4326) NOT NULL,
    observation_type VARCHAR(50) NOT NULL,
    value JSONB NOT NULL,
    uncertainty FLOAT,
    quality_score FLOAT,
    data_source VARCHAR(100) NOT NULL,
    processing_metadata JSONB,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

SELECT create_hypertable('geological_observations', 'timestamp', if_not_exists => TRUE);

CREATE INDEX IF NOT EXISTS idx_geo_obs_timestamp ON geological_observations (timestamp DESC);
CREATE INDEX IF NOT EXISTS idx_geo_obs_location ON geological_observations USING GIST (location);
CREATE INDEX IF NOT EXISTS idx_geo_obs_type ON geological_observations (observation_type);

CREATE TABLE IF NOT EXISTS causal_relationships (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    source_process VARCHAR(100) NOT NULL,
    target_process VARCHAR(100) NOT NULL,
    causal_strength FLOAT NOT NULL,
    confidence_lower FLOAT NOT NULL,
    confidence_upper FLOAT NOT NULL,
    temporal_lag_seconds FLOAT DEFAULT 0,
    spatial_correlation FLOAT DEFAULT 0,
    last_updated TIMESTAMPTZ DEFAULT NOW(),
    validation_score FLOAT DEFAULT 0,
    discovery_method VARCHAR(100),
    is_active BOOLEAN DEFAULT TRUE,
    UNIQUE(source_process, target_process)
);

CREATE INDEX IF NOT EXISTS idx_causal_source ON causal_relationships (source_process);
CREATE INDEX IF NOT EXISTS idx_causal_target ON causal_relationships (target_process);
CREATE INDEX IF NOT EXISTS idx_causal_strength ON causal_relationships (causal_strength DESC);

CREATE TABLE IF NOT EXISTS anomaly_detections (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    timestamp TIMESTAMPTZ NOT NULL,
    anomaly_type VARCHAR(50) NOT NULL,
    process_type VARCHAR(50) NOT NULL,
    station_id VARCHAR(100) NOT NULL,
    anomaly_score FLOAT NOT NULL,
    statistical_significance FLOAT,
    causal_pathway JSONB,
    affected_processes JSONB,
    temporal_pattern JSONB,
    spatial_extent JSONB,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_anomaly_timestamp ON anomaly_detections (timestamp DESC);
CREATE INDEX IF NOT EXISTS idx_anomaly_type ON anomaly_detections (anomaly_type);
CREATE INDEX IF NOT EXISTS idx_anomaly_score ON anomaly_detections (anomaly_score DESC);

CREATE TABLE IF NOT EXISTS baseline_statistics (
    process_type VARCHAR(50) PRIMARY KEY,
    statistics JSONB NOT NULL,
    calculated_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS anomaly_models (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    process_type VARCHAR(50) NOT NULL,
    model_data BYTEA,
    model_parameters JSONB,
    training_data_size INTEGER,
    accuracy_score FLOAT,
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

